// Champs ajoutés pour la facturation électronique (Factur-X) — toujours
// en plus des champs existants, jamais à la place : "address" reste
// l'adresse en un seul bloc telle qu'elle est saisie et imprimée
// aujourd'hui, les nouveaux champs portent les informations que la norme
// EN 16931 exige séparément (code postal, ville, SIRET/SIREN, n° TVA).
function emptyClient() {
  return { id: nextId("cli"), type: "entreprise", name: "", address: "", country: geoDefaults().country, email: "", phone: "", siret: "", tva: "", postalCode: "", city: "" };
}
// Profil d'entreprise sans pays renseigné : proposé avec le pays détecté
// dans le formulaire (l'utilisateur peut le changer avant d'enregistrer).
function withGeoCountry(profile) {
  if (!profile || (profile.country || "").trim()) return profile;
  const { country } = geoDefaults();
  return country ? { ...profile, country } : profile;
}
// Copie du profil entreprise enregistrée dans chaque nouveau document :
// tout ce que les PDF et Factur-X lisent (identité, coordonnées, IBAN, BIC,
// option débits, mentions légales), sans les réglages propres à
// l'application qui n'ont rien à faire dans un document.
const COMPANY_SNAPSHOT_EXCLUDED = ["googleReviewUrl", "fiscalStartMonth", "accounting"];
function companySnapshotOf(profile) {
  const out = { ...(profile || {}) };
  for (const k of COMPANY_SNAPSHOT_EXCLUDED) delete out[k];
  return out;
}
// Champs de l'émetteur et du client repris des fiches (Mon entreprise, fiche
// client liée par clientId ou par nom identique). Seuls les champs VIDES du
// document sont complétés — jamais une valeur saisie ; le type
// (entreprise / particulier) suit la fiche seulement s'il n'est pas déjà
// posé. Importer un client ou son entreprise ne réclame donc rien de plus.
const DOC_COMPANY_FIELDS = ["type", "name", "siret", "tva", "address", "postalCode", "city", "country", "email", "phone", "logo"];
const DOC_CLIENT_FIELDS = ["type", "name", "address", "postalCode", "city", "country", "email", "phone", "siret", "tva"];
const isBlankValue = (v) => v === undefined || v === null || (typeof v === "string" && !v.trim());
function fillBlankFields(target, source, fields) {
  if (!source) return target;
  let out = target;
  for (const f of fields) {
    if (isBlankValue(target?.[f]) && !isBlankValue(source[f])) {
      if (out === target) out = { ...(target || {}) };
      out[f] = source[f];
    }
  }
  return out;
}
// Fiche client d'un document : liée par clientId, sinon nom identique.
function clientRecordOf(doc, clients) {
  if (!doc) return null;
  const list = Array.isArray(clients) ? clients : [];
  return list.find((c) => c.id === doc.clientId) || (doc.client?.name ? findClientByName(list, doc.client.name) : null) || null;
}
function completeDocumentFromRecords(doc, companyProfile, clients) {
  if (!doc) return doc;
  let next = doc;
  if (doc.company && companyProfile && String(companyProfile.name || "").trim()) {
    const company = fillBlankFields(doc.company, companyProfile, DOC_COMPANY_FIELDS);
    if (company !== doc.company) next = { ...next, company };
  }
  const record = clientRecordOf(doc, clients);
  if (record && doc.client) {
    const client = fillBlankFields(doc.client, record, DOC_CLIENT_FIELDS);
    if (client !== doc.client) next = { ...next, client };
    if (!doc.clientId) next = { ...next, clientId: record.id };
  }
  return next;
}
// Client choisi ou reconnu par son nom : toute sa fiche est reprise (type,
// pays, ville, SIRET…), les champs déjà saisis dans le document sont gardés.
function mergeClientRecord(current, record, name) {
  const cur = { ...(current || {}), name };
  if (!record) return cur;
  return { ...fillBlankFields(cur, record, DOC_CLIENT_FIELDS), ...(record.type ? { type: record.type } : {}), name };
}
// Copie d'un document (bouton Dupliquer) : nouveau numéro, brouillon non
// terminé ; tout ce qui appartient à la vie du document d'origine est laissé
// derrière — paiements reçus, date de paiement, acompte versé, signature du
// client, photos de chantier (fichiers partagés) — sinon la copie naissait
// « déjà payée » ou « déjà signée ».
function duplicatedDocumentOf(original, documents) {
  const copy = { ...original, id: nextId("doc"), docNumber: nextNumber(documents, original.type), status: "brouillon", workStage: "brouillon", createdAt: Date.now(), updatedAt: Date.now() };
  delete copy.paidAt;
  if (Array.isArray(copy.payments)) copy.payments = [];
  if (copy.acompteVerse !== undefined) copy.acompteVerse = "";
  if (copy.signature) copy.signature = null;
  if (copy.signatureTechnicien?.name) copy.signatureTechnicien = { ...copy.signatureTechnicien, name: "", date: "" };
  if (Array.isArray(copy.photos) && copy.photos.length) copy.photos = [];
  return copy;
}
// Client enregistré dont le nom correspond (sans tenir compte de la casse ni
// des espaces) : sert à lier automatiquement les documents des éditeurs
// spécialisés, qui n'ont pas de sélecteur de client.
function findClientByName(clients, name) {
  const n = String(name || "").trim().toLowerCase();
  if (!n) return null;
  return (clients || []).find((c) => String(c?.name || "").trim().toLowerCase() === n) || null;
}
function emptyCompanyProfile() {
  return {
    type: "entreprise", name: "", siret: "", address: "", country: "", email: "", phone: "", tva: "", logo: null, postalCode: "", city: "", iban: "", bic: "", vatOnDebits: false, googleReviewUrl: "", fiscalStartMonth: 1,
    // Bloc de paiement et pied de page des factures : nom de la banque, code NAF.
    bankName: "", naf: "",
    // Mentions légales imprimées sur les devis et factures (audit des champs,
    // étape A) : forme juridique, capital, immatriculation RCS/RM (art.
    // R123-237 C. com.), mention « EI » de l'entrepreneur individuel (art.
    // L526-22 C. com.), assurance décennale (art. L243-2 C. assurances),
    // médiateur de la consommation (art. L616-1 C. conso).
    legalForm: "", capital: "", registration: "", entrepreneurIndividuel: false,
    insuranceName: "", insurancePolicy: "", insuranceZone: "",
    mediatorName: "", mediatorContact: "",
  };
}
function nextNumber(documents, type) {
  const prefixes = { devis: "DEV", proforma: "PRO", revision: "REV", acompte: "ACO", avoir: "AVO", commande: "CMD", livraison: "BL", situation: "SIT", pv_reception: "PV", bpu: "BPU", rapport: "RI", contrat: "CTR", relance: "MED", planning: "PLN" };
  const prefix = prefixes[type] || "FAC";
  const nums = documents.filter((d) => d.type === type).map((d) => parseInt((d.docNumber.match(/(\d+)$/) || [])[1] || "0", 10));
  const next = (nums.length ? Math.max(...nums) : 0) + 1;
  return `${prefix}-${String(next).padStart(3, "0")}`;
}

function emptyProforma() {
  return {
    serie: "", incoterm: "", incotermPlace: "",
    paymentTerms: "", grossWeight: "", netWeight: "", packagesCount: "",
    originCountry: "", hsCode: "", loadingPort: "", dischargingPort: "", transportMode: "",
    customFields: [],
  };
}

