    SERVICES.filter((s) => visibleServices.includes(s.id) && s.implemented).forEach((s) => {
      cmds.push({ id: `new-${s.id}`, label: `Nouveau : ${s.label}`, icon: s.icon, hint: "Créer", keywords: s.description, action: () => openNewService(s.id) });
    });
    return cmds;
